effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    float l = dot(src.rgb, vec3(0.299,0.587,0.114));
    vec2 g = acScreenNorm*count;
    vec2 id = floor(g);
    vec2 f = fract(g)-0.5;
    float h = rand(id);
    float tw = 0.5 + 0.5*sin(acTime*speed + h*42.0);
    float cx = smoothstep(0.03,0.0,abs(f.x))*smoothstep(0.45,0.0,abs(f.y));
    float cy = smoothstep(0.03,0.0,abs(f.y))*smoothstep(0.45,0.0,abs(f.x));
    float spark = max(cx,cy)*step(0.82,h)*tw*step(threshold,l);
    gl_FragColor = src + vec4(color.rgb,0.0)*spark;
}
